r"""遗留事项 1 的**诊断器**：图片引用语法审计。

⚠️ 本工具**只报告、不修改**。原因见下。

背景：`kb_lint.check_wikilinks` 只检测 `!{2,}[[`（双感叹号）变体，
**不检测裸 `[[fig.png]]`** —— 这是**有意**的，因为绝大多数裸图片 wikilink
是**有意写的「点开看图」超链接**（`[[x.png|🖼 打开]]`），改成 `![[ ]]`
会让图片在正文里铺开、破坏排版。

初版本工具（2026-09-25）曾按「表格内 = 展示用」的规则自动 `![[ ]]` 化，
**该规则是错的**：本库两份汇报页的表格是「备选图 | 点开看图 | 图号 | 出处」
四列结构，第 3 列的 `[[x.png\|🖼 打开]]` **正是超链接**，改成嵌入等于
在表格单元格里渲染大图。**真值 0 处**，而初版会误改 57 处。

⇒ 结论：**裸图片 wikilink 无法靠启发式判定意图**，必须人读上下文。

真正的判定规则（本工具实现）：
  1. **在代码围栏 / 行内代码内** → 示例文本，**不计**
     （`2026-09-22-deep-lint-report.md` 正是在演示「坏写法长什么样」）
  2. **带别名且别名含「打开 / 查看 / 🖼 / 👁」等** → 交互式超链接，**保留**
  3. **同页正文已用 `![[ ]]` 嵌入过同一文件、此处又裸引** → 重复引用，**可疑**
  4. **别名像图号/短标签、且目标从未在本页嵌入** → 疑似漏 `!`，**可疑**
  5. **目标文件不存在** → 纯装饰性死链，**单独报**

用法：
  python tools/qc_fix_image_syntax.py            # 全库审计
  python tools/qc_fix_image_syntax.py --json     # 机器可读
  python tools/qc_fix_image_syntax.py --selftest # 校验器自检（含 4 号事故回归夹具）
"""
import sys
import os
import re
import glob
import json
import argparse

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text  # noqa: E402
from kb_lib import console_encoding
console_encoding()

# 零宽/不可见字符：只列**零宽** + NBSP，**不要**放普通空格
# （初版曾含 0x20，会把正文正常空格当污染）。
ZERO_WIDTH = "​‌‍⁠﻿ "
ZW_RE = re.compile("[" + ZERO_WIDTH + "]")

# ⚠️ 图片 wikilink 的**唯一正确**匹配式。
#   踩过的坑：写成 r"...\.png(?:\\?\|[^\]]*)?\]\]" 时，
#   **带别名的链接一条也匹配不到** —— 实测 `[[a/fig.png|打开 X]]` 命中 0，
#   去掉那个可选组则命中 1。根因是转义层级在字符组内被解析成
#   字面 `\` + 可选 `|`，而真实文本是裸 `|`，于是可选组无法匹配、
#   后续 `\]\]` 也对不上，**整条链接被静默漏掉**。
#   ⇒ **不要处理转义管道**；用 `[^\]]*` 吞掉别名即可。
IMG_LINK_RE = re.compile(
    r"(?<!!)\[\[([^\]\n]*\.(?:png|jpg|jpeg|gif|webp|svg))([^\]]*)\]\]", re.I)

# 「点开看图」类交互式别名的指纹
HYPERLINK_ALIAS = re.compile(r"打开|查看|看图|点开|点击|🖼|👁|🔍|open", re.I)


def _norm(v):
    """归一化比较用的链接目标"""
    v = ZW_RE.sub("", v)
    v = v.replace("\\|", "|").split("|")[0].split("#")[0].strip()
    return v.replace("\\", "/").strip("/").lower()


def _code_mask(raw):
    """返回与 raw 等长的布尔掩码：True = 该位置在代码块/行内代码内。

    必须剔除，否则「演示坏写法」的报告页会被当成真缺陷
    （正是 `2026-09-22-deep-lint-report.md` 的情形）。
    """
    mask = bytearray(len(raw))
    # 围栏代码块 ``` ... ```
    for m in re.finditer(r"^[ \t]*```[^\n]*\n.*?^[ \t]*```[ \t]*$", raw,
                         re.M | re.S):
        for i in range(m.start(), m.end()):
            mask[i] = 1
    # 行内代码 `...`
    for m in re.finditer(r"`[^`\n]+`", raw):
        for i in range(m.start(), m.end()):
            mask[i] = 1
    return mask


def audit(path):
    raw = read_text(path)
    mask = _code_mask(raw)

    embedded = set()
    for m in re.finditer(r"!\[\[([^\]\n]*)\]\]", raw):
        embedded.add(_norm(m.group(1)))

    suspicious = []   # 疑似漏 !
    hyperlinks = []   # 保留
    examples = []     # 代码块内的示例
    dead = []         # 目标不存在

    for m in IMG_LINK_RE.finditer(raw):
        lineno = raw.count("\n", 0, m.start()) + 1
        whole, tgt_raw, alias = m.group(0), m.group(1), m.group(2)
        tgt = _norm(tgt_raw)

        if any(mask[m.start():m.end()]):
            examples.append((lineno, whole[:80]))
            continue

        # 目标文件是否存在
        tgt_path = tgt.replace("\\", "/")
        exists = os.path.exists(tgt_path) if "/" in tgt_path else None

        if HYPERLINK_ALIAS.search(alias):
            hyperlinks.append((lineno, alias.strip("| ")[:40]))
            continue

        if exists is False:
            dead.append((lineno, whole[:80]))
        elif tgt in embedded:
            suspicious.append((lineno, "同页已嵌入过同一文件，此处又裸引", whole[:80]))
        else:
            suspicious.append((lineno, "别名非交互式、该文件本页未嵌入", whole[:80]))

    return {
        "file": path.replace("\\", "/"),
        "suspicious": suspicious,
        "hyperlinks": hyperlinks,
        "examples": examples,
        "dead": dead,
    }


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    🔴 核心回归夹具 = 本库「校验器自检纪律」**第 4 号事故**：
       初始正则把「带别名的图片 wikilink」一条也匹配不到（命中 0），
       却据此报「34 处图片语法错误」并准备改写 57 处（**真值 0**）。
    故此处必须钉死：**带别名的链接一定要匹配到**。
    """
    ok = True

    # ---- 夹具 1（4 号事故回归）：带别名的裸图片链接必须被匹配到 ----
    s = "| [[raw/assets/a/fig_p4_2.png|p4_2]] |"
    n = len(IMG_LINK_RE.findall(s))
    print(f"  [{'ok' if n == 1 else 'FAIL'}] 4 号事故回归：带别名的裸图片链接命中 -> {n}")
    ok = ok and n == 1
    s = "[[raw/assets/a/fig_p4_2.png\\|p4_2]]"   # 表格转义管道形态
    n = len(IMG_LINK_RE.findall(s))
    print(f"  [{'ok' if n == 1 else 'FAIL'}] 表格转义管道形态命中 -> {n}")
    ok = ok and n == 1
    s = "[[fig.png]]"
    n = len(IMG_LINK_RE.findall(s))
    print(f"  [{'ok' if n == 1 else 'FAIL'}] 无别名的裸图片链接命中 -> {n}")
    ok = ok and n == 1

    # ---- 夹具 2（反例）：已嵌入的 `![[ ]]` 不得被当成「漏 !」的裸链 ----
    s = "![[fig.png]]"
    n = len(IMG_LINK_RE.findall(s))
    print(f"  [{'ok' if n == 0 else 'FAIL'}] 反例 已嵌入的 ![[ ]] 不匹配裸链 -> {n}")
    ok = ok and n == 0

    # ---- 夹具 3：非图片链接不得命中 ----
    s = "[[concepts/固态电解质]]"
    n = len(IMG_LINK_RE.findall(s))
    print(f"  [{'ok' if n == 0 else 'FAIL'}] 反例 非图片 wikilink 不命中 -> {n}")
    ok = ok and n == 0

    # ---- 夹具 4：「点开看图」别名必须被判为超链接（保留，勿改）----
    hit = bool(HYPERLINK_ALIAS.search("|🖼 打开"))
    print(f"  [{'ok' if hit else 'FAIL'}] 交互式别名指纹命中「🖼 打开」")
    ok = ok and hit
    miss = bool(HYPERLINK_ALIAS.search("|p4_2"))
    print(f"  [{'ok' if not miss else 'FAIL'}] 反例 普通图号别名不判为超链接")
    ok = ok and not miss

    # ---- 夹具 5：代码块内的示例必须被掩码剔除 ----
    raw = "```\n[[fig.png|别名]]\n```\n正文 [[real.png]]\n"
    mask = _code_mask(raw)
    inside = [m for m in IMG_LINK_RE.finditer(raw) if any(mask[m.start():m.end()])]
    outside = [m for m in IMG_LINK_RE.finditer(raw) if not any(mask[m.start():m.end()])]
    got = len(inside) == 1 and len(outside) == 1
    print(f"  [{'ok' if got else 'FAIL'}] 代码块示例被剔除、正文保留 "
          f"(in={len(inside)} out={len(outside)})")
    ok = ok and got

    # ---- 夹具 6：零宽字符归一 ----
    got = _norm("​raw/assets/x/F​ig.png")
    print(f"  [{'ok' if got == 'raw/assets/x/fig.png' else 'FAIL'}] 零宽字符归一 -> {got}")
    ok = ok and got == "raw/assets/x/fig.png"

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="图片引用语法审计（只报告，不修改）")
    ap.add_argument("--json", action="store_true", help="机器可读")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    as_json = args.json

    targets = []
    for d in ("outputs", "sources", "concepts", "topics", "entities"):
        targets += sorted(glob.glob(f"wiki/{d}/*.md"))

    reports = [r for r in (audit(p) for p in targets)
               if any(r[k] for k in ("suspicious", "hyperlinks", "examples", "dead"))]

    if as_json:
        print(json.dumps(reports, ensure_ascii=False, indent=1))
        return 0

    tot = {"suspicious": 0, "hyperlinks": 0, "examples": 0, "dead": 0}
    print("=== 图片引用语法审计（只报告，不修改）===\n")
    for r in reports:
        print(f"{r['file']}")
        for key, label, icon in (
            ("suspicious", "🔴 疑似漏 `!`（需人读上下文确认）", "   "),
            ("dead", "🔴 目标文件不存在（装饰性死链）", "   "),
            ("examples", "⚪ 代码块内的示例文本（非缺陷）", "   "),
            ("hyperlinks", "✅ 「点开看图」超链接（保留，勿改）", "   "),
        ):
            items = r[key]
            if not items:
                continue
            print(f"  {label}: {len(items)}")
            for it in items[:4]:
                if key == "hyperlinks":
                    print(f"       L{it[0]:<5} 别名={it[1]!r}")
                elif key == "suspicious":
                    print(f"       L{it[0]:<5} [{it[1]}] {it[2]}")
                else:
                    print(f"       L{it[0]:<5} {it[1]}")
            if len(items) > 4:
                print(f"       ... 另 {len(items) - 4} 处")
            tot[key] += len(items)
        print()

    print("=== 合计 ===")
    print("疑似漏 `!`        : %d" % tot["suspicious"])
    print("目标不存在的死链  : %d" % tot["dead"])
    print("代码块示例（非缺陷）: %d" % tot["examples"])
    print("「点开看图」超链接（保留）: %d" % tot["hyperlinks"])
    print("\n⚠️ 本工具不自动修改：裸图片 wikilink 的意图无法靠启发式判定。")
    return 0


if __name__ == "__main__":
    sys.exit(main())
